mapper.select:
select P.payment_no as paymentNo, A.account_name as studentName, P.payment_month as paymentMonth, P.payment_status as paymentStatus, P.payment_amount as totalAmount,
-- 납부 내역(history) 테이블에서 해당 결제건의 납부액을 모두 더함 (없으면 0) NVL((select sum(payment_history_amount) from payment_history where payment_no = P.payment_no), 0) as paidAmount,
-- 총액 - 납부액 = 남은 금액 P.payment_amount - NVL((select sum(payment_history_amount) from payment_history where payment_no = P.payment_no), 0) as remainingAmount,
-- 최근 납부일 (가장 마지막에 돈 낸 날짜) (select max(payment_history_at) from payment_history where payment_no = P.payment_no) as lastPaidDate
from payment P inner join student S on P.student_no = S.student_no inner join account A on S.account_no = A.account_no where 1=1
and P.student_no = #{studentNo}
and P.payment_month = #{searchMonth}
and P.payment_status = #{searchStatus}
and A.account_name like '%' || #{searchName} || '%'
order by P.payment_no desc
